{"file_path":"/home/user/deepseek-harness/.claude/worktrees/agent-a951125abdb93ee06/.proving-ground/runs/polyglot-core-sonnet-20260922T202046Z/cell-1mQTFm/src/lib.rs","content":"pub struct Luhn {
    code: String,
}

impl Luhn {
    pub fn is_valid(&self) -> bool {
        let mut sum = 0;
        let mut digit_count = 0;

        for c in self.code.chars().rev() {
            if c.is_whitespace() {
                continue;
            }

            let digit = match c.to_digit(10) {
                Some(d) => d,
                None => return false,
            };

            let mut value = digit;
            if digit_count % 2 == 1 {
                value *= 2;
                if value > 9 {
                    value -= 9;
                }
            }

            sum += value;
            digit_count += 1;
        }

        digit_count > 1 && sum % 10 == 0
    }
}

impl From<&str> for Luhn {
    fn from(input: &str) -> Self {
        Luhn {
            code: input.to_string(),
        }
    }
}

impl From<String> for Luhn {
    fn from(input: String) -> Self {
        Luhn { code: input }
    }
}

macro_rules! impl_from_integer {
    ($($t:ty),*) => {
        $(
            impl From<$t> for Luhn {
                fn from(input: $t) -> Self {
                    Luhn {
                        code: input.to_string(),
                    }
                }
            }
        )*
    };
}

impl_from_integer!(u8, u16, u32, u64, usize);
"}

