#include <cstddef>
#include <stdexcept>

namespace linked_list {

template <typename T>
class List {
   public:
    List() = default;

    ~List() {
        Node* current = head_;
        while (current != nullptr) {
            Node* next = current->next;
            delete current;
            current = next;
        }
    }

    List(const List&) = delete;
    List& operator=(const List&) = delete;

    void push(T value) {
        Node* node = new Node{value, tail_, nullptr};
        if (tail_ != nullptr) {
            tail_->next = node;
        } else {
            head_ = node;
        }
        tail_ = node;
        ++count_;
    }

    void unshift(T value) {
        Node* node = new Node{value, nullptr, head_};
        if (head_ != nullptr) {
            head_->prev = node;
        } else {
            tail_ = node;
        }
        head_ = node;
        ++count_;
    }

    T pop() {
        if (tail_ == nullptr) {
            throw std::out_of_range("pop from empty list");
        }
        Node* node = tail_;
        T value = node->value;
        tail_ = node->prev;
        if (tail_ != nullptr) {
            tail_->next = nullptr;
        } else {
            head_ = nullptr;
        }
        delete node;
        --count_;
        return value;
    }

    T shift() {
        if (head_ == nullptr) {
            throw std::out_of_range("shift from empty list");
        }
        Node* node = head_;
        T value = node->value;
        head_ = node->next;
        if (head_ != nullptr) {
            head_->prev = nullptr;
        } else {
            tail_ = nullptr;
        }
        delete node;
        --count_;
        return value;
    }

    bool erase(const T& value) {
        Node* current = head_;
        while (current != nullptr) {
            if (current->value == value) {
                if (current->prev != nullptr) {
                    current->prev->next = current->next;
                } else {
                    head_ = current->next;
                }
                if (current->next != nullptr) {
                    current->next->prev = current->prev;
                } else {
                    tail_ = current->prev;
                }
                delete current;
                --count_;
                return true;
            }
            current = current->next;
        }
        return false;
    }

    std::size_t count() const { return count_; }

   private:
    struct Node {
        T value;
        Node* prev;
        Node* next;
    };

    Node* head_ = nullptr;
    Node* tail_ = nullptr;
    std::size_t count_ = 0;
};

}  // namespace linked_list
"}

