    const Complex c2{0.0, 2.0};

    require_approx_equal(Complex(-2.0, 0.0), c1 * c2);
}

TEST_CASE("Arithmetic -> Multiplication -> Multiply numbers with real and imaginary part", "[4d1d10f0-f8d4-48a0-b1d0-f284ada567e6]") {
