TEST_CASE("Complex conjugate -> Conjugate a purely imaginary number", "[e37fe7ac-a968-4694-a460-66cb605f8691]") {
    const Complex c{0.0, 5.0};

    require_approx_equal(Complex(0.0, -5.0), c.conj());
