TEST_CASE("Complex exponential function -> Euler's identity/formula", "[6d96d4c6-2edb-445b-94a2-7de6d4caaf60]") {
    const Complex c{0.0, M_PI};

    require_approx_equal(Complex(-1.0, 0.0), c.exp());
