    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("invalid number of pins")
        if self._is_game_over():
            raise IndexError("cannot roll after game is over")
        if not self._roll_is_valid(pins):
            raise ValueError("invalid roll")
        self.rolls.append(pins)

    def _roll_is_valid(self, pins):
        frame_index = 0
        i = 0
        while i < len(self.rolls) and frame_index < 9:
            if self.rolls[i] == 10:
                i += 1
            else:
                i += 2
            frame_index += 1

        if frame_index < 9:
            # still within frames 1-9
            if i < len(self.rolls) and self.rolls[i] != 10:
                # second throw of a non-strike frame
                if self.rolls[i] + pins > 10:
                    return False
            return True

        # in the tenth frame
        tenth = self.rolls[i:]
        tenth = tenth + [pins]
        if len(tenth) == 2:
            if tenth[0] != 10 and tenth[0] + tenth[1] > 10:
                return False
        elif len(tenth) == 3:
            if tenth[0] == 10:
                if tenth[1] != 10 and tenth[1] + tenth[2] > 10:
                    return False
            elif tenth[0] + tenth[1] == 10:
                pass
            else:
                return False
        return True

    def _is_game_over(self):
        frame_index = 0
        i = 0
        while i < len(self.rolls) and frame_index < 9:
            if self.rolls[i] == 10:
                i += 1
            else:
                i += 2
            frame_index += 1

        if frame_index < 9:
            return False

        tenth = self.rolls[i:]
        if len(tenth) == 0:
            return False
        if tenth[0] == 10 or (len(tenth) >= 2 and tenth[0] + tenth[1] == 10):
            return len(tenth) >= 3
        return len(tenth) >= 2

    def score(self):
        if not self._is_game_over():
            raise IndexError("game is not over")

        total = 0
        i = 0
        for _ in range(10):
            if self.rolls[i] == 10:
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                i += 1
            elif self.rolls[i] + self.rolls[i + 1] == 10:
                total += 10 + self.rolls[i + 2]
                i += 2
            else:
                total += self.rolls[i] + self.rolls[i + 1]
                i += 2
        return total
