{"file_path":"src/lib.rs","content":"use std::collections::HashMap;
use std::thread;

pub fn frequency(input: &[&str], worker_count: usize) -> HashMap<char, usize> {
    if input.is_empty() {
        return HashMap::new();
    }

    let worker_count = worker_count.max(1).min(input.len());
    let chunk_size = input.len().div_ceil(worker_count);

    thread::scope(|scope| {
        let handles: Vec<_> = input
            .chunks(chunk_size)
            .map(|chunk| {
                scope.spawn(move || {
                    let mut counts = HashMap::new();
                    for line in chunk {
                        for c in line.chars() {
                            if let Some(letter) = c.to_lowercase().next() {
                                if letter.is_alphabetic() {
                                    *counts.entry(letter).or_insert(0) += 1;
                                }
                            }
                        }
                    }
                    counts
                })
            })
            .collect();

        let mut total = HashMap::new();
        for handle in handles {
            let counts = handle.join().unwrap();
            for (letter, count) in counts {
                *total.entry(letter).or_insert(0) += count;
            }
        }
        total
    })
}
"}

