{"file_path":"perfect_numbers.cpp","content":"#include "perfect_numbers.h"

#include <stdexcept>

namespace perfect_numbers {

classification classify(int number) {
    if (number <= 0) {
        throw std::domain_error("Classification is only possible for positive integers.");
    }

    int aliquot_sum = 0;
    for (int divisor = 1; divisor * divisor <= number; ++divisor) {
        if (number % divisor == 0) {
            int other = number / divisor;
            if (divisor != number) {
                aliquot_sum += divisor;
            }
            if (other != divisor && other != number) {
                aliquot_sum += other;
            }
        }
    }

    if (aliquot_sum == number) {
        return classification::perfect;
    }
    if (aliquot_sum > number) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
"}

