{"file_path":"clock.cpp","content":"#include "clock.h"
#include <sstream>
#include <iomanip>

namespace date_independent {

namespace {

int normalize(int total_minutes)
{
    constexpr int minutes_per_day = 24 * 60;
    int result = total_minutes % minutes_per_day;
    if (result < 0) {
        result += minutes_per_day;
    }
    return result;
}

}  // namespace

clock::clock(int hour, int minute)
    : hour_(0), minute_(0)
{
    int total = normalize(hour * 60 + minute);
    hour_ = total / 60;
    minute_ = total % 60;
}

clock clock::at(int hour, int minute)
{
    return clock(hour, minute);
}

clock clock::plus(int minutes) const
{
    return clock(hour_, minute_ + minutes);
}

clock::operator std::string() const
{
    std::ostringstream oss;
    oss << std::setw(2) << std::setfill('0') << hour_ << ":"
        << std::setw(2) << std::setfill('0') << minute_;
    return oss.str();
}

bool clock::operator==(const clock& other) const
{
    return hour_ == other.hour_ && minute_ == other.minute_;
}

bool clock::operator!=(const clock& other) const
{
    return !(*this == other);
}

}  // namespace date_independent
"}

